# ── 纯 numpy 前向传播 ──────────────────────────────────────

def _linear(x, w, b):
    """x: (N, in_features), w: (out, in), b: (out,) → (N, out)"""
    return x @ w.T + b


def _batchnorm(x, weight, bias, running_mean, running_var, eps=BN_EPS):
    """inference-mode BatchNorm1d."""
    x_hat = (x - running_mean) / np.sqrt(running_var + eps)
    return x_hat * weight + bias


def _relu(x):
    return np.maximum(x, 0.0)


def dl_forward(factor_matrix, w):
    """
    factor_matrix: (N_stocks, 75) — 截面标准化后的因子值 (NaN→0)
    w: 权重字典 (由 _load_dl_weights 返回)
    返回: (N_stocks,) 股票得分向量
    """
    x = np.nan_to_num(factor_matrix).astype(np.float64)

    # Layer 0: Linear(75→64)
    x = _linear(x, w['net.0.weight'], w['net.0.bias'])
    x = _batchnorm(x, w['net.1.weight'], w['net.1.bias'],
                   w['net.1.running_mean'], w['net.1.running_var'])
    x = _relu(x)

    # Layer 1: Linear(64→32)
    x = _linear(x, w['net.4.weight'], w['net.4.bias'])
    x = _batchnorm(x, w['net.5.weight'], w['net.5.bias'],
                   w['net.5.running_mean'], w['net.5.running_var'])
    x = _relu(x)

    # Layer 2: Linear(32→16)
    x = _linear(x, w['net.8.weight'], w['net.8.bias'])
    x = _batchnorm(x, w['net.9.weight'], w['net.9.bias'],
                   w['net.9.running_mean'], w['net.9.running_var'])
    x = _relu(x)

    # Layer 3: Linear(16→1)
    x = _linear(x, w['net.12.weight'], w['net.12.bias'])
    return x.squeeze(-1)


# ═══════════════════════════════════════════════════════════════════
# 因子计算 (按组归类, 共享中间量)
# ═══════════════════════════════════════════════════════════════════

def _rolling_window(arr, window, func, axis=-1):
    """对 arr 沿 axis 做 rolling(func). 返回与 arr 同 shape (前 window-1 为 NaN)."""
    n = arr.shape[axis]
    result = np.full(arr.shape, np.nan, dtype=np.float64)
    for i in range(window - 1, n):
        slc = [slice(None)] * arr.ndim
        slc[axis] = slice(i - window + 1, i + 1)
        slc = tuple(slc)
        result_slc = [slice(None)] * result.ndim
        result_slc[axis] = i
        result_slc = tuple(result_slc)
        result[result_slc] = func(arr[slc])
    return result


def _ewm(arr, span, axis=-1):
    """指数加权平均 (近似)."""
    alpha = 2.0 / (span + 1)
    n = arr.shape[axis]
    result = np.full(arr.shape, np.nan, dtype=np.float64)
    slc0 = [slice(None)] * arr.ndim
    slc0[axis] = 0
    result[tuple(slc0)] = arr[tuple(slc0)]
    for i in range(1, n):
        slc_prev = [slice(None)] * arr.ndim
        slc_prev[axis] = i - 1
        slc_curr = [slice(None)] * arr.ndim
        slc_curr[axis] = i
        result[tuple(slc_curr)] = alpha * arr[tuple(slc_curr)] + (1 - alpha) * result[tuple(slc_prev)]
    return result


def _rank_pct(arr):
    """百分比排名. NaN → NaN."""
    mask = np.isfinite(arr)
    out = np.full(len(arr), np.nan, dtype=np.float64)
    if mask.sum() < 2:
        return out
    ranks = rankdata(arr[mask])
    out[mask] = ranks / len(ranks)
    return out


def compute_factors_week(open_arr, high_arr, low_arr, close_arr, vol_arr,
                         fundamental_map):
    """
    计算给定截面日 75 个因子值 (所有股票).

    参数:
      open_arr, high_arr, low_arr, close_arr, vol_arr: (LOOKBACK, N_stocks) numpy 数组
      fundamental_map: dict {股票 → {ep, bp, sp, cfp, mcap, circ_mcap, ...}}

    返回: dict {factor_name → (N_stocks,) numpy 数组}
    """
    result = {}
    N = close_arr.shape[1]

    # ── 公共中间量 ──
    ret_1d = np.diff(close_arr, axis=0) / (close_arr[:-1] + 1e-12)  # (T-1, N)
    ret_1d = np.vstack([np.full((1, N), np.nan), ret_1d])            # (T, N)
    log_vol = np.log(vol_arr + 1)
    dollar_vol = close_arr * vol_arr
    hl_ratio = (high_arr - low_arr) / (close_arr + 1e-12)

    # ── 收益率因子 ──
    # ret_1m: 最近21日收益
    ret_1m = close_arr[-1] / (close_arr[-21] + 1e-12) - 1 if close_arr.shape[0] >= 21 else np.full(N, np.nan)
    result['ret_1m'] = ret_1m
    result['ret_3m'] = close_arr[-1] / (close_arr[-63] + 1e-12) - 1 if close_arr.shape[0] >= 63 else np.full(N, np.nan)
    result['ret_6m'] = close_arr[-1] / (close_arr[-126] + 1e-12) - 1 if close_arr.shape[0] >= 126 else np.full(N, np.nan)
    result['ret_12m'] = close_arr[-1] / (close_arr[-252] + 1e-12) - 1 if close_arr.shape[0] >= 252 else np.full(N, np.nan)
    # ret_1m_skip1m: t-42 ~ t-21 收益
    if close_arr.shape[0] >= 42:
        result['ret_1m_skip1m'] = close_arr[-21] / (close_arr[-42] + 1e-12) - 1
    else:
        result['ret_1m_skip1m'] = np.full(N, np.nan)

    # ret_open_2d_proxy: (open/open_2d_ago - 1) 简化
    if open_arr.shape[0] >= 3:
        result['ret_open_2d_proxy'] = open_arr[-1] / (open_arr[-3] + 1e-12) - 1
    else:
        result['ret_open_2d_proxy'] = np.full(N, np.nan)

    # price_1m: (close - close_21d) / close_21d (与ret_1m同但常用于截面)
    result['price_1m'] = ret_1m.copy()

    # rank_1m: ret_1m 的截面排名
    result['rank_1m'] = _rank_pct(ret_1m)

    # short_rev_5d: -5日收益 (反转因子)
    if close_arr.shape[0] >= 6:
        result['short_rev_5d'] = -(close_arr[-1] / (close_arr[-6] + 1e-12) - 1)
    else:
        result['short_rev_5d'] = np.full(N, np.nan)

    # max_ret_1m: 最近21日最大单日收益
    if ret_1d.shape[0] >= 21:
        result['max_ret_1m'] = np.max(ret_1d[-21:], axis=0)
    else:
        result['max_ret_1m'] = np.full(N, np.nan)

    # ── OHLCV 量价因子 ──
    # money_flow_20: MFI 简化版
    if close_arr.shape[0] >= 21:
        typical = (high_arr[-21:] + low_arr[-21:] + close_arr[-21:]) / 3.0
        mf = typical * vol_arr[-21:]
        pos_flow = np.sum(mf * (typical[-1] > typical), axis=0)
        neg_flow = np.sum(mf * (typical[-1] <= typical), axis=0)
        mfr = pos_flow / (neg_flow + 1e-12)
        result['money_flow_20'] = 100.0 - 100.0 / (1.0 + mfr)
    else:
        result['money_flow_20'] = np.full(N, np.nan)

    # bull_power: (high - EMA13(close))
    ema13 = _ewm(close_arr, 13, axis=0)[-1]
    result['bull_power'] = high_arr[-1] - ema13

    # bear_power: (low - EMA13(close))
    result['bear_power'] = low_arr[-1] - ema13

    # tvma_20: (close - MA20)
    if close_arr.shape[0] >= 20:
        ma20 = np.mean(close_arr[-20:], axis=0)
        result['tvma_20'] = close_arr[-1] - ma20
    else:
        result['tvma_20'] = np.full(N, np.nan)

    # gap_up: open / prev_close - 1
    if close_arr.shape[0] >= 2:
        result['gap_up'] = open_arr[-1] / (close_arr[-2] + 1e-12) - 1
    else:
        result['gap_up'] = np.full(N, np.nan)

    # opening_gap_momentum: 过去N日开盘跳空动量
    if open_arr.shape[0] >= 21 and close_arr.shape[0] >= 22:
        gaps = open_arr[-21:] / (np.roll(close_arr, 1, axis=0)[-21:] + 1e-12) - 1
        result['opening_gap_momentum'] = np.mean(gaps, axis=0)
    else:
        result['opening_gap_momentum'] = np.full(N, np.nan)

    # overnight_5d: 隔夜收益 (open/prev_close - 1) 的 5日均值
    if close_arr.shape[0] >= 6:
        on_ret = open_arr[-5:] / (np.roll(close_arr, 1, axis=0)[-5:] + 1e-12) - 1
        result['overnight_5d'] = np.mean(on_ret, axis=0)
    else:
        result['overnight_5d'] = np.full(N, np.nan)

    # intraday_reversal: -(close - open) / open (日内的反转)
    result['intraday_reversal'] = -(close_arr[-1] - open_arr[-1]) / (open_arr[-1] + 1e-12)

    # high_low_range: (high - low) / close
    result['high_low_range'] = hl_ratio[-1]

    # high_52w_dist: (52周最高 - close) / 52周最高
    if close_arr.shape[0] >= 252:
        h52 = np.max(high_arr[-252:], axis=0)
        result['high_52w_dist'] = (h52 - close_arr[-1]) / (h52 + 1e-12)
    else:
        result['high_52w_dist'] = np.full(N, np.nan)

    # high_52w_rank: close 在 52周内的排名
    if close_arr.shape[0] >= 252:
        h52_rank = np.array([_rank_pct(close_arr[-252:, i])[-1] for i in range(N)])
        result['high_52w_rank'] = h52_rank
    else:
        result['high_52w_rank'] = np.full(N, np.nan)

    # panic_selling: 当日跌幅是否 > 3σ (简化: 当日收益 / 20日std)
    if ret_1d.shape[0] >= 20:
        std20 = np.std(ret_1d[-20:], axis=0)
        result['panic_selling'] = -ret_1d[-1] / (std20 + 1e-12)
    else:
        result['panic_selling'] = np.full(N, np.nan)

    # ── 波动率因子 ──
    if ret_1d.shape[0] >= 63:
        result['vol_1m'] = np.std(ret_1d[-21:], axis=0) * np.sqrt(252)
        result['vol_3m'] = np.std(ret_1d[-63:], axis=0) * np.sqrt(252)
    else:
        result['vol_1m'] = np.full(N, np.nan)
        result['vol_3m'] = np.full(N, np.nan)
    if ret_1d.shape[0] >= 20:
        result['downside_vol'] = np.std(np.minimum(ret_1d[-20:], 0), axis=0) * np.sqrt(252)
    else:
        result['downside_vol'] = np.full(N, np.nan)

    # volatility_of_volatility: 20日波动率的 20日标准差
    if ret_1d.shape[0] >= 40:
        vol_20d_s = np.array([np.std(ret_1d[i:i+20, j]) for i in range(ret_1d.shape[0]-19) for j in range(N)]).reshape(-1, N)
        # 简化: 直接用最后20日波动率的std
        result['volatility_of_volatility'] = np.std(ret_1d[-20:], axis=0)
    else:
        result['volatility_of_volatility'] = np.full(N, np.nan)

    # skew_1m, skewness_20
    if ret_1d.shape[0] >= 21:
        result['skew_1m'] = np.array([skew(ret_1d[-21:, i]) for i in range(N)])
    else:
        result['skew_1m'] = np.full(N, np.nan)
    if ret_1d.shape[0] >= 20:
        result['skewness_20'] = np.array([skew(ret_1d[-20:, i]) for i in range(N)])
    else:
        result['skewness_20'] = np.full(N, np.nan)

    # kurtosis_20
    if ret_1d.shape[0] >= 20:
        result['kurtosis_20'] = np.array([kurtosis(ret_1d[-20:, i]) for i in range(N)])
    else:
        result['kurtosis_20'] = np.full(N, np.nan)

    # sharpe_20
    if ret_1d.shape[0] >= 20:
        mu = np.mean(ret_1d[-20:], axis=0)
        std = np.std(ret_1d[-20:], axis=0)
        result['sharpe_20'] = mu / (std + 1e-12) * np.sqrt(252)
    else:
        result['sharpe_20'] = np.full(N, np.nan)

    # range_consistency: (high-low) / (high-low)的std
    if hl_ratio.shape[0] >= 20:
        result['range_consistency'] = np.mean(hl_ratio[-20:], axis=0) / (np.std(hl_ratio[-20:], axis=0) + 1e-12)
    else:
        result['range_consistency'] = np.full(N, np.nan)

    # max_drawdown_duration: 近似 (最长连续下跌天数)
    if close_arr.shape[0] >= 60:
        dd = np.zeros(N)
        for i in range(N):
            s = close_arr[-60:, i]
            streak = 0
            mx = 0
            for j in range(1, len(s)):
                if s[j] < s[j-1]:
                    streak += 1
                    mx = max(mx, streak)
                else:
                    streak = 0
            dd[i] = mx
        result['max_drawdown_duration'] = dd
    else:
        result['max_drawdown_duration'] = np.full(N, np.nan)

    # ── 成交量/流动性因子 (JQ: turnover → volume 代理) ──
    # volume_ratio: volume / MA20(volume)
    if vol_arr.shape[0] >= 20:
        ma20v = np.mean(vol_arr[-20:], axis=0)
        result['volume_ratio'] = vol_arr[-1] / (ma20v + 1)
    else:
        result['volume_ratio'] = np.full(N, np.nan)

    # vroc_12: (volume - volume_12d_ago) / volume_12d_ago
    if vol_arr.shape[0] >= 13:
        result['vroc_12'] = vol_arr[-1] / (vol_arr[-13] + 1) - 1
    else:
        result['vroc_12'] = np.full(N, np.nan)

    # vpt: 量价趋势 (cumsum of volume * ret)
    if vol_arr.shape[0] >= 20:
        result['vpt'] = np.sum(vol_arr[-20:] * ret_1d[-20:], axis=0)
    else:
        result['vpt'] = np.full(N, np.nan)

    # vr_26: 26日量比 (up_vol / down_vol)
    if vol_arr.shape[0] >= 27:
        up_vol = np.sum(vol_arr[-26:] * (ret_1d[-26:] > 0), axis=0)
        down_vol = np.sum(vol_arr[-26:] * (ret_1d[-26:] < 0), axis=0) + 1
        result['vr_26'] = up_vol / down_vol
    else:
        result['vr_26'] = np.full(N, np.nan)

    # davol_20: 日均成交额 (元)
    if close_arr.shape[0] >= 20:
        result['davol_20'] = np.mean(dollar_vol[-20:], axis=0)
    else:
        result['davol_20'] = np.full(N, np.nan)

    # abnormal_turnover: volume / MA(volume, 50) - 1
    if vol_arr.shape[0] >= 50:
        result['abnormal_turnover'] = vol_arr[-1] / (np.mean(vol_arr[-50:], axis=0) + 1) - 1
    else:
        result['abnormal_turnover'] = np.full(N, np.nan)

    # turnover_change: MA5(volume) / MA20(volume) (代理换手变化)
    if vol_arr.shape[0] >= 20:
        ma5v = np.mean(vol_arr[-5:], axis=0)
        ma20v = np.mean(vol_arr[-20:], axis=0)
        result['turnover_change'] = ma5v / (ma20v + 1)
    else:
        result['turnover_change'] = np.full(N, np.nan)

    # turnover_cv_20d: volume CV (std/mean)
    if vol_arr.shape[0] >= 20:
        mu_v = np.mean(vol_arr[-20:], axis=0)
        std_v = np.std(vol_arr[-20:], axis=0)
        result['turnover_cv_20d'] = std_v / (mu_v + 1)
    else:
        result['turnover_cv_20d'] = np.full(N, np.nan)

    # turnover_std: std(volume, 20)
    if vol_arr.shape[0] >= 20:
        result['turnover_std'] = np.std(vol_arr[-20:], axis=0)
    else:
        result['turnover_std'] = np.full(N, np.nan)

    # turnover_to_vol: mean(volume, 20) / std(ret, 20) (代理换手/波动)
    if vol_arr.shape[0] >= 20 and ret_1d.shape[0] >= 20:
        result['turnover_to_vol'] = np.mean(vol_arr[-20:], axis=0) / (np.std(ret_1d[-20:], axis=0) + 1e-12)
    else:
        result['turnover_to_vol'] = np.full(N, np.nan)

    # avg_turnover_1m: -mean(volume, 20) (代理)
    if vol_arr.shape[0] >= 20:
        result['avg_turnover_1m'] = -np.mean(vol_arr[-20:], axis=0)
    else:
        result['avg_turnover_1m'] = np.full(N, np.nan)

    # volume_climax_reversal: volume / MA50(volume) (放量反转)
    if vol_arr.shape[0] >= 50:
        result['volume_climax_reversal'] = vol_arr[-1] / (np.mean(vol_arr[-50:], axis=0) + 1)
    else:
        result['volume_climax_reversal'] = np.full(N, np.nan)

    # volume_stability: 1 - CV(volume, 20)
    if vol_arr.shape[0] >= 20:
        mu_v = np.mean(vol_arr[-20:], axis=0)
        std_v = np.std(vol_arr[-20:], axis=0)
        result['volume_stability'] = 1.0 - std_v / (mu_v + 1e-12)
    else:
        result['volume_stability'] = np.full(N, np.nan)

    # attention_decay: 成交量衰减 (近期量 / 远期量 - 1)
    if vol_arr.shape[0] >= 40:
        recent = np.mean(vol_arr[-10:], axis=0)
        distant = np.mean(vol_arr[-40:-10], axis=0)
        result['attention_decay'] = recent / (distant + 1) - 1
    else:
        result['attention_decay'] = np.full(N, np.nan)

    # amihud_illiq: |ret| / dollar_vol 的 20日均值
    if ret_1d.shape[0] >= 20 and close_arr.shape[0] >= 20:
        illiq = np.abs(ret_1d[-20:]) / (dollar_vol[-20:] + 1)
        result['amihud_illiq'] = np.mean(illiq, axis=0)
    else:
        result['amihud_illiq'] = np.full(N, np.nan)

    # dollar_vol_20d: -log(mean(dollar_vol, 20)) (取负, 高成交额=高分)
    if close_arr.shape[0] >= 20:
        dv = np.log(np.mean(dollar_vol[-20:], axis=0) + 1)
        result['dollar_vol_20d'] = -dv
    else:
        result['dollar_vol_20d'] = np.full(N, np.nan)

    # dollar_vol_stability: 1 - CV(dollar_vol, 20)
    if close_arr.shape[0] >= 20:
        mu_dv = np.mean(dollar_vol[-20:], axis=0)
        std_dv = np.std(dollar_vol[-20:], axis=0)
        result['dollar_vol_stability'] = 1.0 - std_dv / (mu_dv + 1e-12)
    else:
        result['dollar_vol_stability'] = np.full(N, np.nan)

    # ── 技术指标因子 ──
    # rsi_14
    if close_arr.shape[0] >= 15:
        diffs = np.diff(close_arr[-15:], axis=0)
        up = np.sum(np.maximum(diffs, 0), axis=0)
        down = np.sum(np.abs(np.minimum(diffs, 0)), axis=0)
        rs = up / (down + 1e-12)
        result['rsi_14'] = 100.0 - 100.0 / (1.0 + rs)
    else:
        result['rsi_14'] = np.full(N, np.nan)

    # boll_pct_b: (close - lower) / (upper - lower)
    if close_arr.shape[0] >= 20:
        ma20 = np.mean(close_arr[-20:], axis=0)
        std20 = np.std(close_arr[-20:], axis=0)
        upper = ma20 + 2 * std20
        lower = ma20 - 2 * std20
        result['boll_pct_b'] = (close_arr[-1] - lower) / (upper - lower + 1e-12)
    else:
        result['boll_pct_b'] = np.full(N, np.nan)

    # bias_20: (close - MA20) / MA20
    if close_arr.shape[0] >= 20:
        ma20 = np.mean(close_arr[-20:], axis=0)
        result['bias_20'] = (close_arr[-1] - ma20) / (ma20 + 1e-12)
    else:
        result['bias_20'] = np.full(N, np.nan)

    # cci_14
    if close_arr.shape[0] >= 14:
        tp = (high_arr[-14:] + low_arr[-14:] + close_arr[-14:]) / 3
        ma_tp = np.mean(tp, axis=0)
        md = np.mean(np.abs(tp - ma_tp), axis=0)
        result['cci_14'] = (tp[-1] - ma_tp) / (0.015 * md + 1e-12)
    else:
        result['cci_14'] = np.full(N, np.nan)

    # psy_12: 12日中上涨天数/12
    if ret_1d.shape[0] >= 12:
        result['psy_12'] = np.mean(ret_1d[-12:] > 0, axis=0)
    else:
        result['psy_12'] = np.full(N, np.nan)

    # roc_20: (close - close_20d) / close_20d
    if close_arr.shape[0] >= 21:
        result['roc_20'] = close_arr[-1] / (close_arr[-21] + 1e-12) - 1
    else:
        result['roc_20'] = np.full(N, np.nan)

    # streak: 连续同向天数 (正=连涨, 负=连跌)
    if close_arr.shape[0] >= 2:
        streak_arr = np.zeros(N)
        for i in range(N):
            s = close_arr[:, i]
            s = s[~np.isnan(s)]
            if len(s) < 2:
                continue
            direction = np.sign(s[-1] - s[-2])
            count = 1
            for j in range(len(s) - 2, 0, -1):
                if np.sign(s[j] - s[j-1]) == direction:
                    count += 1
                else:
                    break
            streak_arr[i] = count * direction
        result['streak'] = streak_arr
    else:
        result['streak'] = np.full(N, np.nan)

    # trend_persistence_score: 趋势持续度 (20日线性回归 R²)
    if close_arr.shape[0] >= 20:
        x = np.arange(20, dtype=np.float64)
        x_mean = x.mean()
        ssx = np.sum((x - x_mean) ** 2)
        tps = np.zeros(N)
        for i in range(N):
            y = close_arr[-20:, i]
            mask = np.isfinite(y)
            if mask.sum() < 10:
                tps[i] = np.nan
                continue
            y_m = y[mask][:10]  # 简化
            if len(y_m) < 5:
                tps[i] = np.nan
                continue
            x_m = x[:len(y_m)]
            ssx_m = np.sum((x_m - x_m.mean()) ** 2)
            if ssx_m < 1e-12:
                tps[i] = np.nan
                continue
            slope = np.sum((x_m - x_m.mean()) * (y_m - y_m.mean())) / ssx_m
            intercept = y_m.mean() - slope * x_m.mean()
            y_pred = slope * x_m + intercept
            ss_res = np.sum((y_m - y_pred) ** 2)
            ss_tot = np.sum((y_m - y_m.mean()) ** 2)
            tps[i] = 1.0 - ss_res / (ss_tot + 1e-12)
        result['trend_persistence_score'] = tps
    else:
        result['trend_persistence_score'] = np.full(N, np.nan)

    # trend_smoothness: 1 - CV(close, 20)
    if close_arr.shape[0] >= 20:
        mu = np.mean(close_arr[-20:], axis=0)
        std = np.std(close_arr[-20:], axis=0)
        result['trend_smoothness'] = 1.0 - std / (mu + 1e-12)
    else:
        result['trend_smoothness'] = np.full(N, np.nan)

    # plrc_12: 价格线性回归斜率(12日) / close
    if close_arr.shape[0] >= 12:
        x = np.arange(12, dtype=np.float64)
        x_mean = x.mean()
        ssx = np.sum((x - x_mean) ** 2)
        slopes = np.zeros(N)
        for i in range(N):
            y = close_arr[-12:, i]
            if not np.isfinite(y).all():
                slopes[i] = np.nan
            else:
                slopes[i] = np.sum((x - x_mean) * (y - y.mean())) / (ssx + 1e-12)
        result['plrc_12'] = slopes / (close_arr[-1] + 1e-12)
    else:
        result['plrc_12'] = np.full(N, np.nan)

    # ── 基本面因子 (从 fundamental_map 取) ──
    # 这些在调用 compute_factors_week 前已经预先加载
    for f in ['ep', 'bp', 'sp', 'cfp', 'ln_mcap', 'ln_circulating_mcap',
              'f_score', 'accrual_quality_proxy', 'earnings_quality_proxy',
              'earnings_consistency_proxy', 'earnings_season_vol_div',
              'capital_efficiency_proxy', 'cashflow_matching_proxy',
              'operational_efficiency_proxy', 'earnings_volume_drift',
              'post_earnings_stability']:
        # 从 fundamental_map 中提取
        arr = np.full(N, np.nan)
        for si in range(N):
            if si < len(fundamental_map.get(f, [])):
                arr[si] = fundamental_map.get(f, [np.nan])[si]
        result[f] = arr

    return result


# ═══════════════════════════════════════════════════════════════════
# 价格加载 (已验证, 逐字段取价)
# ═══════════════════════════════════════════════════════════════════

def _get_price_field(stocks, end_dt, count, field):
    """逐字段取价, 跨 Panel/DataFrame 兼容."""
    px = get_price(stocks, end_date=end_dt, count=count,
                   frequency='daily', fields=field,
                   skip_paused=False, fq='pre')
    _Panel = getattr(pd, 'Panel', None)
    if _Panel is not None and isinstance(px, _Panel):
        px = px[field] if field in getattr(px, 'items', []) else px.minor_xs(field)
    return px


# ═══════════════════════════════════════════════════════════════════
# JQ 主策略
# ═══════════════════════════════════════════════════════════════════

def initialize(context):
    """聚宽初始化."""
    g.weights_loaded = False
    g.dl_weights = None
    g.lookback = LOOKBACK
    g.hold_n = HOLD_N

    set_benchmark(BENCHMARK)
    set_option('use_real_price', True)
    set_option('avoid_future_data', True)

    # 成本
    set_order_cost(OrderCost(
        open_tax=0, close_tax=TAX,
        open_commission=COMMISSION, close_commission=COMMISSION,
        close_today_commission=0, min_commission=0
    ), type='stock')
    set_slippage(FixedSlippage(SLIPPAGE))

    # 周频调仓
    run_weekly(main, weekday=4, time='14:50')


def main(context):
    """每周调仓."""
    # 延迟加载权重 (首次)
    if g.dl_weights is None:
        g.dl_weights = _load_dl_weights(g)
        log.info('DL model weights loaded (%d tensors)', len(g.dl_weights))

    # 1. 股票池
    stocks = _get_pool(context)
    log.info('[DL] pool=%d stocks (need>=%d)', len(stocks), HOLD_N)
    if len(stocks) < HOLD_N:
        log.warn('[DL] SKIP: pool too small (%d < %d)', len(stocks), HOLD_N)
        return

    # 2. 分块取价 (逐字段, 与 V5 相同的已验证逻辑)
    CHUNK = 500
    open_arr_list, high_arr_list, low_arr_list = [], [], []
    close_arr_list, vol_arr_list, stock_order = [], [], []
    end_dt = context.previous_date
    n_chunk_ok = 0
    n_stock_ok = 0
    first_chunk_shape = None

    for i in range(0, len(stocks), CHUNK):
        chunk = stocks[i:i + CHUNK]
        try:
            open_df   = _get_price_field(chunk, end_dt, LOOKBACK, 'open')
            high_df   = _get_price_field(chunk, end_dt, LOOKBACK, 'high')
            low_df    = _get_price_field(chunk, end_dt, LOOKBACK, 'low')
            close_df  = _get_price_field(chunk, end_dt, LOOKBACK, 'close')
            volume_df = _get_price_field(chunk, end_dt, LOOKBACK, 'volume')
            if first_chunk_shape is None:
                first_chunk_shape = open_df.shape
                log.info('[DL] chunk#%d get_price OK, open_df shape=%s, type=%s, cols[:3]=%s',
                         i // CHUNK, open_df.shape, type(open_df).__name__,
                         str(list(open_df.columns[:3])))
            n_chunk_ok += 1
        except Exception as e:
            log.warn('[DL] chunk#%d get_price FAILED: %s', i // CHUNK, str(e)[:120])
            continue

        for s in chunk:
            try:
                o = open_df[s].values.astype(np.float64)
                h = high_df[s].values.astype(np.float64)
                l = low_df[s].values.astype(np.float64)
                c = close_df[s].values.astype(np.float64)
                v = volume_df[s].values.astype(np.float64)
                if len(o) < LOOKBACK:
                    continue
                open_arr_list.append(o)
                high_arr_list.append(h)
                low_arr_list.append(l)
                close_arr_list.append(c)
                vol_arr_list.append(v)
                stock_order.append(s)
                n_stock_ok += 1
            except Exception:
                continue
        del open_df, high_df, low_df, close_df, volume_df
        gc.collect()

    log.info('[DL] price fetch done: %d/%d chunks OK, %d stocks valid',
             n_chunk_ok, (len(stocks) + CHUNK - 1) // CHUNK, n_stock_ok)

    if len(stock_order) < HOLD_N:
        log.warn('[DL] SKIP: valid stocks=%d < HOLD_N=%d', len(stock_order), HOLD_N)
        return

    # 转为 (LOOKBACK, N) 的数组
    N = len(stock_order)
    log.info('[DL] building arrays N=%d...', N)
    open_arr = np.column_stack(open_arr_list)
    high_arr = np.column_stack(high_arr_list)
    low_arr = np.column_stack(low_arr_list)
    close_arr = np.column_stack(close_arr_list)
    vol_arr = np.column_stack(vol_arr_list)

    # 3. 加载基本面 (仅在需要时)
    fundamental_map = _load_fundamentals_batch(context, stock_order)
    log.info('[DL] fundamentals loaded, keys=%d', len(fundamental_map))

    # 4. 计算全部 75 因子
    factors = compute_factors_week(open_arr, high_arr, low_arr, close_arr, vol_arr, fundamental_map)
    log.info('[DL] factors computed: %d/%d present', len(factors), DL_N_FACTORS)

    # 5. 构建因子矩阵 (N × 75), 截面 z-score
    factor_matrix = np.full((N, DL_N_FACTORS), np.nan, dtype=np.float64)
    n_avail = 0
    for fi, fname in enumerate(DL_FACTOR_NAMES):
        if fname in factors:
            factor_matrix[:, fi] = factors[fname]
            n_avail += 1

    log.info('[DL] factor matrix: %d/%d factors available in this chunk', n_avail, DL_N_FACTORS)

    # 截面 z-score 标准化 (与训练完全一致)
    n_zscored = 0
    for fi in range(DL_N_FACTORS):
        col = factor_matrix[:, fi]
        mask = np.isfinite(col)
        if mask.sum() < 50:
            factor_matrix[:, fi] = 0.0
            continue
        mu = np.nanmean(col[mask])
        sigma = np.nanstd(col[mask])
        if sigma < 1e-8:
            factor_matrix[:, fi] = 0.0
        else:
            factor_matrix[mask, fi] = (col[mask] - mu) / sigma
            factor_matrix[~mask, fi] = 0.0
            n_zscored += 1

    # 6. DL 前向传播 → 得分
    scores = dl_forward(factor_matrix, g.dl_weights)
    valid_scores = np.sum(np.isfinite(scores))
    log.info('[DL] forward done: valid scores=%d/%d, range=[%.3f, %.3f]',
             valid_scores, N, scores[np.isfinite(scores)].min() if valid_scores > 0 else np.nan,
             scores[np.isfinite(scores)].max() if valid_scores > 0 else np.nan)

    # 7. 选股
    valid_mask = np.isfinite(scores)
    if valid_mask.sum() < HOLD_N:
        log.warn('[DL] SKIP: valid scores=%d < HOLD_N=%d', valid_mask.sum(), HOLD_N)
        return

    sorted_idx = np.argsort(scores[valid_mask])[::-1][:HOLD_N]
    buy_list = [stock_order[i] for i in np.where(valid_mask)[0][sorted_idx]]

    # 8. 调仓 (等权 — 若后续需 HRP 可加)
    current_holdings = list(context.portfolio.positions.keys())
    for s in current_holdings:
        if s not in buy_list:
            order_target_value(s, 0)

    if len(buy_list) > 0:
        weight = context.portfolio.total_value / len(buy_list)
        for s in buy_list:
            order_target_value(s, weight)

    log.info('DLv1 | 持仓:%d | 得分范围:[%.2f, %.2f]' % (
        len(buy_list), scores[valid_mask].min(), scores[valid_mask].max()))

    del open_arr, high_arr, low_arr, close_arr, vol_arr, factor_matrix
    gc.collect()


def _get_pool(context):
    """股票池: 中证全指, 过滤ST/停牌/涨停."""
    try:
        universe = get_index_stocks(INDEX_CODE)
    except Exception:
        universe = get_index_stocks(INDEX_CODE)

    pool = []
    current_data = get_current_data()
    for s in universe:
        try:
            cd = current_data[s]
            if cd is None:
                continue
            if cd.paused:
                continue
            if cd.is_st:
                continue
            # 涨停过滤
            if cd.high_limit <= cd.last_price:
                continue
            pool.append(s)
        except Exception:
            pool.append(s)
    return pool


def _load_fundamentals_batch(context, stocks):
    """批量加载基本面数据 (适配 JQ 聚宽)."""
    result = {}
    prev_date = context.previous_date
    N = len(stocks)

    # 估值因子
    try:
        q = query(valuation.code, valuation.pe_ratio, valuation.pb_ratio,
                  valuation.ps_ratio, valuation.pcf_ratio,
                  valuation.market_cap, valuation.circulating_market_cap
                  ).filter(valuation.code.in_(stocks))
        val_df = get_fundamentals(q, date=prev_date)
        if val_df is not None and len(val_df) > 0:
            val_df.index = val_df['code']
            # ep = 1/PE
            pe = val_df['pe_ratio'].values.astype(np.float64)
            result['ep'] = np.where(pe > 0, 1.0 / (pe + 1e-12), np.nan)
            # bp = 1/PB
            pb = val_df['pb_ratio'].values.astype(np.float64)
            result['bp'] = np.where(pb > 0, 1.0 / (pb + 1e-12), np.nan)
            # sp = 1/PS
            ps = val_df['ps_ratio'].values.astype(np.float64)
            result['sp'] = np.where(ps > 0, 1.0 / (ps + 1e-12), np.nan)
            # cfp = 1/PCF
            pcf = val_df['pcf_ratio'].values.astype(np.float64)
            result['cfp'] = np.where(pcf > 0, 1.0 / (pcf + 1e-12), np.nan)
            # ln_mcap
            mcap = val_df['market_cap'].values.astype(np.float64)
            result['ln_mcap'] = np.log(mcap + 1)
            # ln_circulating_mcap
            circ_mcap = val_df['circulating_market_cap'].values.astype(np.float64)
            result['ln_circulating_mcap'] = np.log(circ_mcap + 1)
    except Exception:
        pass

    # 质量/基本面代理因子 (JQ中简易实现)
    # 大部分基本面代理在本地是用财务报表计算的, JQ中用简化替代
    for f in ['f_score', 'accrual_quality_proxy', 'earnings_quality_proxy',
              'earnings_consistency_proxy', 'earnings_season_vol_div',
              'capital_efficiency_proxy', 'cashflow_matching_proxy',
              'operational_efficiency_proxy', 'earnings_volume_drift',
              'post_earnings_stability']:
        if f not in result:
            result[f] = np.full(N, 0.0)  # JQ 中暂用 0 (平均) 替代

    return result
